True def transform(grid):
    """Reduce each 3x3 tile to its non-background marker color.

    Colors 0 and 5 are the tile background; each tile contains at most one
    marker color, which is copied to the corresponding output cell.
    """
    h, w = len(grid), len(grid[0])
    return [
        [next((grid[3*r+i][3*c+j]
               for i in range(3) for j in range(3)
               if grid[3*r+i][3*c+j] not in (0, 5)), 0)
         for c in range(w // 3)]
        for r in range(h // 3)
    ]
